class Diagnostic(v22r4.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._antenna_line_online_monitoring = AntennaLineOnlineMonitoring(driver, download_checker)
        self._lte_downlink = TestModelsLTEDownlinkPage(driver, download_checker)
        self._downlink = TestModelsNRDownlinkPage(driver)
        self._sanity_checker = SanityCheckerPage(driver)

    @property
    def antenna_line_online_monitoring(self):
        return self._antenna_line_online_monitoring

    @property
    def lte_downlink(self):
        return self._lte_downlink

    @property
    def sanity_checker(self):
        return self._sanity_checker


class AntennaLineOnlineMonitoring(NavigatablePage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'Antenna Line Online Monitoring']

    def __init__(self, driver, download_checker):
        super(AntennaLineOnlineMonitoring, self).__init__(driver)
        self._view_panel = AntennaLineOnlineMonitoringViewPanel(driver, download_checker)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def select_antenna_lines_for_monitoring(self, antenna_lines=None, timeout=60):
        self._view_panel.select_antenna_lines_for_monitoring(antenna_lines)

    def start_antenna_line_monitoring(self, timeout=60):
        return self._view_panel.start_antenna_line_monitoring(timeout)

    def stop_antenna_line_monitoring(self, timeout=60):
        return self._view_panel.stop_antenna_line_monitoring(timeout)

    def get_monitored_values(self, value_type=None, timeout=60):
        return self._view_panel.get_monitored_values(value_type, timeout)

    def export_monitored_value_to_csv(self, timeout=60):
        return self._view_panel.export_monitored_value_to_csv(timeout)


class AntennaLineOnlineMonitoringViewPanel(ViewPanel):
    COLLAPSE_BUTTON = '//antenna-line-tree-list//i'
    ANT_LINE_WITHOUT_NAME = '//antenna-line-tree-list//i/following-sibling::div//label'
    ANT_LINE_WITH_NAME = '//antenna-line-tree-list//i/following-sibling::div[//span[text()="{}"]]//label'
    CHILD_ANT_NAME = ANT_LINE_WITH_NAME + '/ancestor::li/following-sibling::li//label/following-sibling::span[1]'
    CHILD_ANT_XPATH = ANT_LINE_WITH_NAME + ('/ancestor::li/following-sibling::li//'
                                            'label/following-sibling::span[text()="{}"]')
    CHILD_ANT_LABEL = CHILD_ANT_XPATH + '/preceding-sibling::label'
    CHILD_ANT_CHECKBOX = CHILD_ANT_XPATH + '/preceding-sibling::label//input'

    START_BUTTON = '//ant-monitoring-action-buttons//button[contains(text(), "Start")]'
    STOP_BUTTON = '//ant-monitoring-action-buttons//button[contains(text(), "Stop")]'
    START_MONITORING = '//ant-monitoring-action-buttons//span[contains(text(), "Start monitoring")]'
    MONITORING_ONGOING = '//ant-monitoring-action-buttons//span[contains(text(), "Monitoring is ongoing")]'
    STOP_MONITORING = '//ant-monitoring-action-buttons//span[contains(text(), "Stop monitoring")]'
    MONITORING_COMPLETED = '//ant-monitoring-action-buttons//span[contains(text(), "Stopping monitoring completed")]'

    HEADER_TITLE = '//expansion-panel//expansion-panel-header//ng-transclude'
    FIXED_TABLE_TITLE = ('(//expansion-panel)[{}]//ant-monitoring-results-table'
                         '//*[contains(@class, "ant-monitoring-result-table-fixed")]//thead//th')
    FIXED_TABLE_TR = ('(//expansion-panel)[{}]//ant-monitoring-results-table//*[contains(@class, '
                      '"ant-monitoring-result-table-fixed")]/table/tbody')
    MUTABLE_TABLE_TITLE = ('(//expansion-panel)[{}]//ant-monitoring-results-table'
                           '//*[contains(@class, "ant-monitoring-result-table-container")]//thead//th')
    MUTABLE_TABLE_TR = ('(//expansion-panel)[{}]//ant-monitoring-results-table//*[contains(@class, '
                        '"ant-monitoring-result-table-container")]/table/tbody')
    EXPORT_TO_CSV_BUTTON = '//ant-monitoring-results-panels//button[contains(text(), "Export")]'

    def __init__(self, driver, download_checker):
        super(AntennaLineOnlineMonitoringViewPanel, self).__init__(driver, download_checker)

    def select_antenna_lines_for_monitoring(self, antenna_lines=None, timeout=60):  # noqa: C901
        self.wait_for_visibility_by_xpath(self.COLLAPSE_BUTTON, timeout)
        for elem in self.driver.find_elements_by_xpath(self.COLLAPSE_BUTTON):
            if "expand" in elem.get_attribute("class"):
                elem.click()

        if not antenna_lines:
            for elem in self.driver.find_elements_by_xpath(self.ANT_LINE_WITHOUT_NAME):
                elem.click()
            return

        for ant_line_name, ant_child_names in antenna_lines.items():
            real_ant_names = [elem.text for elem in self.driver.find_elements_by_xpath(
                self.CHILD_ANT_NAME.format(ant_line_name))]
            for name in real_ant_names:
                checkbox = self.CHILD_ANT_CHECKBOX.format(ant_line_name, name)
                elem = self.driver.find_element_by_xpath(checkbox)
                checkbox_elem = self.driver.find_element_by_xpath(self.CHILD_ANT_LABEL.format(ant_line_name, name))
                if not elem.is_selected() and name in ant_child_names:
                    checkbox_elem.click()
                if elem.is_selected() and name not in ant_child_names:
                    checkbox_elem.click()

    def start_antenna_line_monitoring(self, timeout=60):
        self.click_enabled_element((By.XPATH, self.START_BUTTON), timeout)
        modal = AntennaLineOnlineMonitoringModal(self.driver)
        if modal.wait_until_monitoring_modal_appear():
            modal.start()
        self.wait_for_visibility_by_xpath(self.MONITORING_ONGOING, timeout)
        return self.driver.find_element_by_xpath(self.MONITORING_ONGOING).text

    def stop_antenna_line_monitoring(self, timeout=60):
        self.click_enabled_element((By.XPATH, self.STOP_BUTTON), timeout)
        self.wait_for_visibility_by_xpath(self.STOP_MONITORING, timeout)
        self.wait_for_visibility_by_xpath(self.MONITORING_COMPLETED, timeout)
        return self.driver.find_element_by_xpath(self.MONITORING_COMPLETED).text

    def get_monitored_values(self, value_type=None, timeout=60):
        info = {}
        for ind, title_elem in enumerate(self.driver.find_elements_by_xpath(self.HEADER_TITLE)):
            index = ind + 1
            fixed_table_title = self.FIXED_TABLE_TITLE.format(index)
            mutable_table_title = self.MUTABLE_TABLE_TITLE.format(index)

            fixed_monitored_infos = []
            mutable_monitored_infos = []
            for tbody_ind in range(len(self.driver.find_elements_by_xpath(self.FIXED_TABLE_TR.format(index)))):
                fixed_table_tr = (self.FIXED_TABLE_TR + '[{}]/tr').format(index, tbody_ind + 1)
                mutable_table_tr = (self.MUTABLE_TABLE_TR + '[{}]/tr').format(index, tbody_ind + 1)
                fixed_monitored_info = self._get_monitored_table(fixed_table_title, fixed_table_tr, timeout)
                mutable_monitored_info = self._get_monitored_table(mutable_table_title, mutable_table_tr, timeout)
                fixed_monitored_infos.extend(fixed_monitored_info)
                mutable_monitored_infos.extend(mutable_monitored_info)

            monitored_info = []
            title = title_elem.text.split(" ", 1)[0]
            for item in zip(fixed_monitored_infos, mutable_monitored_infos):
                item[0].update(item[1])
                monitored_info.append(item[0])
            final_info = self._final_deal_with_info(monitored_info)
            info.update({title: final_info})

        if value_type:
            return info[value_type]
        return info

    def _final_deal_with_info(self, info):
        new_info = []
        for line in info:
            line_keys = list(line.keys())
            line_values = list(line.values())
            try:
                index = line_values.index(list(filter(lambda x: '\n' in x, line_values))[0])
                for i in range(2):
                    new_values = line_values[:index] + [item.split("\n")[i] for item in line_values[index:]]
                    new_info.append(dict(zip(line_keys, new_values)))
            except IndexError:
                pass
        return new_info if new_info else info

    def _get_monitored_table(self, table_title_xpath, table_tr_xpath, timeout=60):
        monitored_table_info = []
        table_headers = self.get_fields_info_from_row(table_title_xpath, timeout)
        headers = []
        for value in table_headers:
            if '\n' in value:
                value = value.replace('\n', ' ')
            headers.append(value)
        table_trs_rowspan_list, table_trs_value_list = self._get_rowspan_and_tr_value(table_tr_xpath)
        table_value_list = self._format_data_by_rowspan(table_trs_rowspan_list, table_trs_value_list)
        for tr_value in table_value_list:
            monitored_table_info.append(dict(zip(headers, tr_value)))
        return monitored_table_info

    def _get_rowspan_and_tr_value(self, tr_xpath):
        trs_rowspan_list = []
        trs_value_list = []
        for index, tr_elem in enumerate(self.driver.find_elements_by_xpath(tr_xpath)):
            rowspan_list, value_list = [], []
            for td_elem in tr_elem.find_elements_by_xpath('td'):
                rowspan = td_elem.get_attribute('rowspan')
                rowspan_list.append(int(rowspan) if rowspan else 1)

                value_list.append(td_elem.text)
            trs_rowspan_list.append(rowspan_list)
            trs_value_list.append(value_list)
        return trs_rowspan_list, trs_value_list

    def _format_data_by_rowspan(self, trs_rowspan_list, trs_value_list):
        """
        Param "trs_rowspan_list" is a list that contains all value of "rowspan" attribute in "td" label from "tr" labels
        Param "trs_value_list" is a list that contains all value of "td" label from "tr" labels

        "trs_rowspan_list" is like as below:
        [[a0(rows=4), b0(rows=8), c0(rows=4), d0(rows=4), e0(rows=1), f0(rows=1), g0(rows=1), h0(rows=1), i0(rows=4)],
         [e1, f1, g1, h1],  --> all elements that do not exist in this line will be migrated from first line
         [e2, f2, g2, h2],  --> same as above
         [e3, f3, g3, h3],  --> as above
         [a4(rows=4), c4(rows=4), d4(rows=4), e4(rows=1), f4(rows=1), g4(rows=1), h4(rows=1), i4(rows=4)],
                            --> the number "8" in first line will be inserted in this line on index "1"
         [e5, f5, g5, h5],  --> all elements that do not exist in this line will be migrated from fifth line
         [e6, f6, g6, h6],  --> same as above
         [e7, f7, g7, h7]]  --> same as above

         After data format, "trs_rowspan_list" will be like a matrix as below:
        [[a0, b0, c0, d0, e0, f0, g0, h0, i0],
         [a0, b0, c0, d0, e1, f1, g1, h1, i0],
         [a0, b0, c0, d0, e2, f2, g2, h2, i0],
         [a0, b0, c0, d0, e3, f3, g3, h3, i0],
         [a4, b0, c4, d4, e4, f4, g4, h4, i4],
         [a4, b0, c4, d4, e5, f5, g5, h5, i4],
         [a4, b0, c4, d4, e6, f6, g6, h6, i4],
         [a4, b0, c4, d4, e7, f7, g7, h7, i4]]

         All elements in "trs_value_list" will be format by "trs_rowspan_list".
        """
        first_rowspan = trs_rowspan_list[0]
        trs_values = copy.deepcopy(trs_value_list)
        first_tr_value = trs_values[0]

        for index, rowspan in enumerate(trs_rowspan_list[1:]):
            start = first_rowspan.index(rowspan[0])
            end = start + len(rowspan)

            if first_rowspan[start: end] == rowspan:
                for value in first_tr_value[:start][::-1]:
                    trs_values[index + 1].insert(0, value)
                trs_values[index + 1].extend(first_tr_value[end:])
            else:
                max_span = max(first_rowspan)
                f_rowspan = copy.deepcopy(first_rowspan)
                tr_value = trs_values[index + 1]
                for count in range(Counter(first_rowspan).get(max_span)):
                    index_of_max_value = f_rowspan.index(max_span)
                    tr_value.insert(index_of_max_value + count, first_tr_value[index_of_max_value + count])
                    f_rowspan.pop(index_of_max_value)
        return trs_values

    def export_monitored_value_to_csv(self, timeout=60):
        start_time = time.time()
        self.click_enabled_element((By.XPATH, self.EXPORT_TO_CSV_BUTTON), timeout)
        return self.download_files(start_time, timeout)


class TestModelsLTEDownlinkPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'Test Models', 'LTE Downlink']

    def __init__(self, driver, download_checker):
        super(TestModelsLTEDownlinkPage, self).__init__(driver)
        self._view_panel = TestModelsLTEDownlinkPageViewPanel(driver, download_checker)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def start_lte_downlink_test(self, local_cell, test_model, physical_cell_id=None, ul_dl_configuration=None,
                                timeout=60, **kwargs):
        self._view_panel.start_lte_downlink_test(local_cell=local_cell,
                                                 test_model=test_model,
                                                 physical_cell_id=physical_cell_id,
                                                 ul_dl_configuration=ul_dl_configuration,
                                                 timeout=timeout)

    def wait_for_lte_downlink_test_to_start(self, test_id, timeout=90):
        return self._view_panel.wait_for_lte_downlink_test_to_start(test_id, timeout)

    def stop_test(self, test_id, timeout):
        """
        Stops 5G downlink test.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._view_panel.stop_test(test_id, timeout)

    def wait_for_test_to_stop(self, test_id, timeout):
        """
        Waits for test to be successfully started.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._view_panel.wait_for_test_to_stop(test_id, timeout)


class TestModelsLTEDownlinkPageViewPanel(ViewPanel):
    _LOCAL_CELL_LIST_BUTTON_XPATH = '//div[contains(text(), "Local cell")]/parent::*//button'
    _LOCAL_CELL_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "Local cell")]/parent::*//ul//li'
    _TEST_MODEL_LIST_BUTTON_XPATH = '//div[contains(text(), "Test model")]/parent::*//button'
    _TEST_MODEL_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "Test model")]/parent::*//ul//li'
    _PHYSICAL_CELL_ID_INPUT_XPATH = '//div[contains(text(), "Physical cell ID")]/parent::*//input'
    _UL_DL_CONFIGURATION_XPATH = '//div[contains(text(), "UL/DL configuration")]/parent::*//label[text()={}]'
    _START_TEST_BUTTON_XPATH = '//button[contains(text(), "Start Test")]'
    _TEST_TABLE_PROGRESS_CELL_XPATH = '//div[contains(text(), "Started tests")]/parent::*/parent::*//tr[{}]/td[4]'
    _STOP_TEST_BUTTON_XPATH = '//div[contains(text(), "Started tests")]/parent::*/parent::*//tr[{}]//ui-button'

    def __init__(self, driver, download_checker):
        super(TestModelsLTEDownlinkPageViewPanel, self).__init__(driver, download_checker)

    def start_lte_downlink_test(self, local_cell, test_model, physical_cell_id=None,
                                ul_dl_configuration=None, timeout=60):
        self.select_element_from_dropdown_list_by_text_and_click(
            local_cell,
            (By.XPATH, self._LOCAL_CELL_LIST_BUTTON_XPATH),
            (By.XPATH, self._LOCAL_CELL_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )
        self.select_element_from_dropdown_list_by_text_and_click(
            test_model,
            (By.XPATH, self._TEST_MODEL_LIST_BUTTON_XPATH),
            (By.XPATH, self._TEST_MODEL_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )
        if physical_cell_id:
            self.insert_text_to_enabled_element((By.XPATH, self._PHYSICAL_CELL_ID_INPUT_XPATH),
                                                physical_cell_id,
                                                timeout)
        if ul_dl_configuration is not None:
            self.click_enabled_element((By.XPATH, self._UL_DL_CONFIGURATION_XPATH.format(ul_dl_configuration)), timeout)
        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)

    def wait_for_lte_downlink_test_to_start(self, test_id, timeout=90):
        """
        Waits for test to be successfully started.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._check_test_id(test_id)
        try:
            self.wait_for_text_present_in_element((By.XPATH, self._TEST_TABLE_PROGRESS_CELL_XPATH.format(test_id)),
                                                  'succeed',
                                                  timeout)
        except TimeoutException:
            pass
        return self.get_text_by_xpath(self._TEST_TABLE_PROGRESS_CELL_XPATH.format(test_id), timeout)

    @staticmethod
    def _check_test_id(test_id):
        if test_id < 1:
            raise ValueError("Test ID can't be lower then 1 but it was {}".format(test_id))

    def stop_test(self, test_id, timeout):
        """
        Stops 5G downlink test.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._check_test_id(test_id)
        self.click_enabled_element_after_visible((By.XPATH, self._STOP_TEST_BUTTON_XPATH.format(test_id)), timeout)

    def wait_for_test_to_stop(self, test_id, timeout):
        """
        Waits for test to be successfully stopped.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._check_test_id(test_id)
        self.wait_for_text_present_in_element((By.XPATH, self._TEST_TABLE_PROGRESS_CELL_XPATH.format(test_id)),
                                              'Stop succeed.', timeout)


class TestModelsNRDownlinkPage(v22r4.diagnostic.TestModelsNRDownlinkPage):
    def __init__(self, driver):
        super(TestModelsNRDownlinkPage, self).__init__(driver)
        self._view_panel = TestModelsNRDownlinkPageViewPanel(driver)


class TestModelsNRDownlinkPageViewPanel(v22r4.diagnostic.TestModelsNRDownlinkPageViewPanel):
    _POWER_BACKOFF = '//div[contains(text(), "Power backoff")]/parent::*//input'
    _RU_MODE_DROPDOWN_LIST_BUTTON_XPATH = '//div[contains(text(), "RU mode")]/parent::*//button'
    _RU_MODE_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "RU mode")]/parent::*//ul//li'
    _MIMO_RANK_DROPDOWN_LIST_BUTTON_XPATH = '//div[contains(text(), "Mimo rank")]/parent::*//button'
    _MIMO_RANK_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "Mimo rank")]/parent::*//ul//li'

    def start_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id=None,
                   beam_id=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None, type_of_load=None,
                   level_of_load_flat=None, level_of_load_burst=None, spec_ssb_beam_pattern=None,
                   power_backoff=None, ru_mode=None, mimo_rank=None):
        timeout = int(timeout)
        self._configure_downlink_test(local_cell=local_cell,
                                      test_model=test_model,
                                      p_max=p_max,
                                      timeout=timeout,
                                      polarization=polarization,
                                      physical_cell_id=physical_cell_id,
                                      beam_id=beam_id,
                                      nrarfcn_downlink=nrarfcn_downlink,
                                      nrarfcn_uplink=nrarfcn_uplink,
                                      nrarfcn=nrarfcn,
                                      type_of_load=type_of_load,
                                      level_of_load_flat=level_of_load_flat,
                                      level_of_load_burst=level_of_load_burst,
                                      spec_ssb_beam_pattern=spec_ssb_beam_pattern)

        if power_backoff is not None:
            self.insert_text_to_enable_element((By.XPATH, self._POWER_BACKOFF), power_backoff, timeout)

        if ru_mode is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                ru_mode,
                (By.XPATH, self._RU_MODE_DROPDOWN_LIST_BUTTON_XPATH),
                (By.XPATH, self._RU_MODE_DROPDOWN_LIST_OPTIONS_XPATH),
                timeout
            )

        if mimo_rank is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                mimo_rank,
                (By.XPATH, self._MIMO_RANK_DROPDOWN_LIST_BUTTON_XPATH),
                (By.XPATH, self._MIMO_RANK_DROPDOWN_LIST_OPTIONS_XPATH),
                timeout
            )
        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)


